-- DỮ LIỆU SEED KHỞI TẠO: 2. KHO SÁCH (books - 60 ĐẦU SÁCH)
-- =====================================================================
INSERT INTO books (id, title, author, category, quantity, available_copies, description, image_url, status, published_year)
VALUES
  (1, 'Lập Trình Python Cơ Bản Đến Nâng Cao', 'Nguyễn Văn A', 'Công nghệ thông tin', 10, 10, 'Giáo trình toàn diện về Python.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (2, 'Tư Duy Mở', 'Nguyễn Anh Dũng', 'Tâm lý & Kỹ năng sống', 8, 7, 'Cuốn sách truyền cảm hứng mở rộng tầm nhìn, giải phóng tư duy đóng khung và phát triển tiềm năng vô hạn của bản thân trong kỷ nguyên số.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (3, 'Tru Tiên', 'Tiêu Đỉnh', 'Văn học & Tiểu thuyết', 8, 8, 'Bộ tiểu thuyết tiên hiệp kỳ ảo đỉnh cao kể về cuộc đời đầy sóng gió của Trương Tiểu Phàm giữa chánh tà và câu chuyện tình bi tráng.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (4, 'Đấu La Đại Lục', 'Đường Gia Tam Thiếu', 'Văn học & Tiểu thuyết', 8, 8, 'Hành trình rèn luyện võ hồn phi thường của Đường Tam cùng nhóm Sử Lai Khắc Thất Quái trên vùng đất Đấu La huyền bí.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (5, 'Quỷ Bí Chi Chủ', 'Mực Thích Lặn Nước', 'Văn học & Tiểu thuyết', 8, 8, 'Kiệt tác tiểu thuyết phong cách Steampunk và Cthulhu Mythos theo chân Klein Moretti khám phá thế giới phi phàm đầy bí ẩn.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (6, 'Hoàng Tử Bé', 'Antoine de Saint-Exupéry', 'Văn học & Tiểu thuyết', 5, 5, 'Kiệt tác văn học Pháp thấm đượm triết lý nhân văn sâu sắc về tình yêu, sự gắn kết và cách nhìn nhận cuộc sống bằng trái tim.', 'data:image/jpeg;base64,', 'Sẵn sàng', 5),
  (7, 'Những Kẻ Hắc Ám', 'Otsuichi', 'Văn học & Tiểu thuyết', 8, 8, 'Tuyển tập truyện trinh thám tâm lý rùng rợn xoay quanh hai học sinh trung học có niềm đam mê kỳ lạ với những vụ án mạng bí ẩn.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (8, 'Chúa Tể Của Những Chiếc Nhẫn', 'J.R.R. Tolkien', 'Văn học & Tiểu thuyết', 8, 8, 'Thiên sử thi giả tưởng vĩ đại về hành trình gian khổ tiêu diệt Chiếc nhẫn quyền năng tại vùng đất Trung Địa để bảo vệ thế giới.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (9, 'Đêm Trắng', 'Fyodor Dostoevsky', 'Văn học & Tiểu thuyết', 8, 8, 'Khúc ca trữ tình man mác về tình yêu đơn phương và tâm hồn cô đơn của người kể chuyện giữa những đêm trắng lãng mạn thành Petersburg.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (10, 'Thôn Phệ Tinh Không', 'Ngã Cật Tây Hồng Thị', 'Văn học & Tiểu thuyết', 8, 8, 'Thiên truyện khoa học viễn tưởng - tiên hiệp hoành tráng về chiến binh La Phong vươn mình từ Trái Đất bước ra khám phá vũ trụ vô tận.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (11, 'Cửu Đỉnh Ký', 'Ngã Cật Tây Hồng Thị', 'Văn học & Tiểu thuyết', 8, 8, 'Câu chuyện võ thuật kinh điển tái hiện hành trình Đằng Thanh Sơn dung hợp nội gia quyền hiện đại và võ học thượng thừa thời thượng cổ.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (12, 'Tiền Đẻ Ra Tiền', 'Duncan Bannatyne', 'Kinh tế & Kinh doanh', 8, 8, 'Cẩm nang thực tế và thông minh hướng dẫn tư duy đầu tư, quản lý dòng tiền và các chiến lược tạo nguồn thu nhập thụ động hiệu quả.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (13, 'Nghìn Lẻ Một Đêm', 'Truyện cổ Ả Rập', 'Văn học & Tiểu thuyết', 8, 8, 'Tuyển tập những câu chuyện cổ tích Ả Rập kỳ ảo và cuốn hút của nàng Scheherazade thông minh vượt qua ngàn đêm thử thách.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (14, 'Còn Chút Gì Để Nhớ', 'Nguyễn Nhật Ánh', 'Văn học & Tiểu thuyết', 8, 8, 'Tác phẩm giàu cảm xúc tái hiện quãng đời sinh viên hồn nhiên, mối tình đầu trong sáng và những hoài niệm khó quên của một thời tuổi trẻ.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (15, 'Bạn Có Năm Chỗ Ngồi', 'Louise Evans', 'Tâm lý & Kỹ năng sống', 8, 8, 'Phương pháp làm chủ cảm xúc và nghệ thuật lựa chọn hành vi giao tiếp tích cực để xây dựng những mối quan hệ bền vững.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (16, 'Trò Chuyện Với Vĩ Nhân', 'Nhiều tác giả', 'Lịch sử & Xã hội', 8, 8, 'Đúc kết những tư tưởng lớn, nhân sinh quan và bài học sâu sắc từ các danh nhân, triết gia và nhà tư tưởng lỗi lạc qua các thời đại.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (17, 'Đạo Lý Người Xưa', 'Nguyễn Duy Cần', 'Lịch sử & Xã hội', 8, 8, 'Những giá trị đạo đức, phép xử thế và triết lý sống minh triết của tiền nhân được phân tích tinh tế để ứng dụng trong đời sống hiện đại.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (18, 'Mục Thần Ký', 'Trạch Trư', 'Văn học & Tiểu thuyết', 8, 8, 'Thiên tiểu thuyết tiên hiệp hấp dẫn kể về thiếu niên Tần Mục xuất thân từ Tàn Lão Thôn với ý chí quật cường phá vỡ thiên đạo.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (19, 'Đại Niết Bàn', 'Khảo Ngư', 'Văn học & Tiểu thuyết', 8, 8, 'Câu chuyện thanh xuân trùng sinh chân thực, tràn ngập nhiệt huyết tuổi trẻ, nỗ lực phấn đấu làm lại cuộc đời và bảo vệ tình thân.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (20, 'Linh Cảnh Hành Giả', 'Mại Báo Tiểu Lang Quân', 'Văn học & Tiểu thuyết', 8, 8, 'Hành trình khám phá thế giới linh cảnh thần bí, suy luận giải đố nghẹt thở và đối đầu các thế lực siêu nhiên của Trương Nguyên Thanh.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (21, 'Khoa Học Tâm Linh', 'Hoàng Nhật Minh', 'Khoa học & Đời sống', 8, 8, 'Góc nhìn khoa học kết hợp triết học phương Đông lý giải mối liên hệ kỳ diệu giữa năng lượng, tâm thức và quy luật vận hành vũ trụ.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (22, 'Mắt Biếc', 'Nguyễn Nhật Ánh', 'Văn học & Tiểu thuyết', 8, 8, 'Câu chuyện tình đơn phương da diết của Ngạn dành cho Hà Lan gắn liền với làng Đo Đo yên bình và những hoài niệm dang dở.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (23, 'Đọc Vị Bất Kỳ Ai', 'David J. Lieberman', 'Tâm lý & Kỹ năng sống', 8, 8, 'Phương pháp tâm lý học ứng dụng giúp bạn thấu hiểu suy nghĩ, phát hiện nói dối và nắm bắt tâm lý người khác trong mọi cuộc giao tiếp.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (24, 'Báu Vật Của Đời', 'Mạc Ngôn', 'Văn học & Tiểu thuyết', 8, 8, 'Kiệt tác đoạt giải Nobel của Mạc Ngôn khắc họa số phận người mẹ và dân tộc Trung Hoa qua những biến thiên dữ dội của lịch sử thế kỷ 20.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (25, '100 Điều Nên Biết Về Phong Tục Việt Nam', 'Tân Việt', 'Lịch sử & Xã hội', 8, 8, 'Cẩm nang văn hóa tổng hợp các phong tục, lễ nghi, tín ngưỡng và nét đẹp văn hóa truyền thống ngàn đời của dân tộc Việt Nam.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (26, 'Lịch Sử Loài Người', 'Yuval Noah Harari', 'Lịch sử & Xã hội', 8, 8, 'Bức tranh toàn cảnh về sự tiến hóa của loài người từ những sinh vật vô danh trở thành bá chủ Trái Đất qua ba cuộc cách mạng lớn.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (27, 'Thiên Tài Bên Trái - Kẻ Điên Bên Phải', 'Cao Minh', 'Tâm lý & Kỹ năng sống', 8, 8, 'Những cuộc đối thoại kỳ lạ và lôi cuốn với các bệnh nhân tâm thần, mở ra những góc nhìn độc đáo, kỳ dị và sâu sắc về thế giới.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (28, 'Tây Du Ký', 'Ngô Thừa Ân', 'Văn học & Tiểu thuyết', 8, 8, 'Một trong Tứ đại danh tác kinh điển của văn học Trung Hoa kể về hành trình thỉnh kinh vượt 81 kiếp nạn của bốn thầy trò Đường Tăng.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (29, 'Thép Đã Tôi Thế Đấy', 'Nikolai Ostrovsky', 'Văn học & Tiểu thuyết', 8, 8, 'Tác phẩm kinh điển về ý chí, nghị lực sắt đá và tinh thần cống hiến lý tưởng cao đẹp của người thanh niên Pavel Korchagin.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (30, 'Không Gia Đình', 'Hector Malot', 'Văn học & Tiểu thuyết', 8, 8, 'Hành trình phiêu lưu đầy gian nan, lòng quả cảm và nhân ái của cậu bé mồ côi Remi cùng gánh xiếc rong trên khắp nẻo đường nước Pháp.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (31, 'Toàn Chân Triết Luận', 'Nguyễn Duy Cần', 'Lịch sử & Xã hội', 8, 8, 'Tác phẩm luận giải sâu sắc các tư tưởng triết học Đông - Tây, hướng con người tới sự tự do tư tưởng và chân lý toàn vẹn.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (32, 'Phật Học Tinh Hoa', 'Nguyễn Duy Cần', 'Lịch sử & Xã hội', 8, 8, 'Khái quát những giáo lý cốt lõi, tinh hoa triết học Phật giáo một cách mạch lạc, khoa học và dễ tiếp cận cho người đọc hiện đại.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (33, 'Dịch Học Tinh Hoa', 'Nguyễn Duy Cần', 'Lịch sử & Xã hội', 8, 8, 'Phân tích tường tận nguồn gốc, nguyên lý Âm Dương, Bát quái và ứng dụng thực tiễn của Kinh Dịch trong nhân sinh và đời sống.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (34, 'Trang Tử Tâm Đắc', 'Vu Đan', 'Tâm lý & Kỹ năng sống', 8, 8, 'Diễn giải triết lý Trang Tử bằng ngôn ngữ hiện đại, giúp giải tỏa áp lực, nuôi dưỡng tâm hồn thảnh thơi và an nhiên tự tại.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (35, 'Thế Giới Của Sophie', 'Jostein Gaarder', 'Văn học & Tiểu thuyết', 8, 8, 'Cuốn tiểu thuyết nhập môn triết học phương Tây hấp dẫn kể về cô bé Sophie và những bức thư bí ẩn mở ra cánh cửa tri thức vĩ đại.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (36, 'Tôi Tự Học', 'Nguyễn Duy Cần', 'Tâm lý & Kỹ năng sống', 8, 8, 'Cẩm nang phương pháp luận tự học, rèn luyện tư duy độc lập và mở mang tri thức giá trị trường tồn qua nhiều thế hệ học giả.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (37, 'Chủ Nghĩa Khắc Kỷ', 'William B. Irvine', 'Tâm lý & Kỹ năng sống', 8, 8, 'Hướng dẫn ứng dụng triết học Khắc kỷ cổ đại vào đời sống hiện đại để giữ vững sự bình thản và tìm thấy niềm vui sống đích thực.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (38, 'Chiến Thắng Con Quỷ Trong Bạn', 'Napoleon Hill', 'Tâm lý & Kỹ năng sống', 8, 8, 'Tác phẩm đột phá vạch trần nỗi sợ hãi, sự trì hoãn và các cạm bẫy tâm lý kìm hãm con người đạt tới thành công và tự do.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (39, 'Cách Sống Từ Bình Thường Trở Nên Phi Thường', 'Inamori Kazuo', 'Tâm lý & Kỹ năng sống', 8, 8, 'Triết lý kinh doanh và phong cách sống chính trực, tận tụy và kiên định của huyền thoại kinh doanh Nhật Bản Inamori Kazuo.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (40, 'Cái "Dũng" của Thánh Nhân', 'Nguyễn Duy Cần', 'Tâm lý & Kỹ năng sống', 8, 8, 'Bàn về đức điềm đạm, sự tự chủ và nội lực tĩnh tại của bậc thánh nhân trước mọi sóng gió và biến cố cuộc đời.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (41, 'Tư Duy Nhanh và Chậm', 'Daniel Kahneman', 'Tâm lý & Kỹ năng sống', 8, 8, 'Khám phá hai hệ thống tư duy chi phối nhận thức, các thiên kiến tâm lý và cách chúng ta đưa ra quyết định mỗi ngày.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (42, 'Sống 365 Ngày Một Năm', 'John A. Schindler', 'Khoa học & Đời sống', 8, 8, 'Lời khuyên y khoa và tâm lý học thiết thực giúp kiểm soát cảm xúc, phòng ngừa bệnh tật do căng thẳng và sống vui vẻ mỗi ngày.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (43, 'Người Bán Hàng Vĩ Đại Nhất Thế Giới', 'Og Mandino', 'Kinh tế & Kinh doanh', 8, 8, 'Những cuốn da dê bí truyền chứa đựng bài học sâu sắc về sự kiên trì, tình yêu thương và triết lý thành công trong bán hàng và cuộc sống.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (44, 'Sức Mạnh Của Sự Tử Tế', 'Piero Ferrucci', 'Tâm lý & Kỹ năng sống', 8, 8, 'Tác phẩm cảm động khẳng định lòng nhân ái, sự sẻ chia và tử tế chính là nguồn sức mạnh chữa lành tâm hồn và thay đổi thế giới.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (45, 'Đắc Nhân Tâm', 'Dale Carnegie', 'Tâm lý & Kỹ năng sống', 8, 8, 'Cuốn sách nghệ thuật thu phục lòng người bán chạy nhất mọi thời đại với những nguyên tắc vàng trong ứng xử và giao tiếp.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (46, 'Tuổi Trẻ Đáng Giá Bao Nhiêu ?', 'Rosie Nguyễn', 'Tâm lý & Kỹ năng sống', 8, 8, 'Cuốn sách gối đầu giường của giới trẻ Việt Nam về hành trình tự học, đọc sách, trải nghiệm và định hình ước mơ cuộc đời.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (47, 'Khác Biệt Hay Là Chết', 'Jack Trout, Steve Rivkin', 'Kinh tế & Kinh doanh', 8, 8, 'Nguyên lý định vị thương hiệu và chiến lược tạo sự khác biệt cốt lõi để doanh nghiệp tồn tại và bứt phá trên thị trường cạnh tranh.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (48, 'Muôn Kiếp Nhân Sinh', 'Nguyên Phong', 'Lịch sử & Xã hội', 8, 8, 'Bức tranh toàn cảnh về luật nhân quả, luân hồi và những bài học cảnh tỉnh nhân loại qua các tiền kiếp kỳ lạ của tác giả tại Atlantis và Ai Cập.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (49, 'Nhà Giả Kim', 'Paulo Coelho', 'Văn học & Tiểu thuyết', 8, 8, 'Câu chuyện ngụ ngôn tuyệt đẹp về hành trình theo đuổi vận mệnh và lắng nghe tiếng gọi trái tim của chàng chăn cừu Santiago.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (50, 'Giận', 'Thích Nhất Hạnh', 'Tâm lý & Kỹ năng sống', 8, 8, 'Hướng dẫn nghệ thuật chuyển hóa cơn giận, chữa lành tổn thương nội tâm và tìm lại bình an, hạnh phúc trong các mối quan hệ.', 'data:image/jpeg;base64,', 'Sẵn sàng', 8),
  (51, 'Ao no Hako Season 2', 'Kouji Miura', 'Manga & Thể thao', 0, 0, 'Tác phẩm truyện tranh thể thao học đường đình đám kết hợp cầu lông và bóng rổ. Phần tiếp theo khai thác giải đấu liên trường quốc gia và những cung bậc cảm xúc lãng mạn tuổi trẻ. Dự kiến phát hành: 04-10-2026.', 'https://cdn.myanimelist.net/images/anime/1341/145349.jpg', 'Sắp phát hành', 5),
  (52, 'Tensei Kizoku, Kantei Skill de Nariagaru', 'Miraijin A', 'Light Novel & Kỳ ảo', 0, 0, 'Hành trình phát triển lãnh địa của quý tộc Ars Louvent nhờ kỹ năng thẩm định thần thánh chiêu mộ hiền tài bảo vệ vương quốc. Dự kiến phát hành: 10-2026.', 'https://cdn.myanimelist.net/images/anime/1763/139538.jpg', 'Sắp phát hành', 20),
  (53, 'Ma Thuật Đặc Biệt Của Pháp Sư Tái Sinh', 'Yuusan', 'Kỳ ảo & Hành động', 0, 0, 'Pháp sư tài ba thức tỉnh sau hàng thế kỷ trong thời đại ma thuật mới suy tàn và bắt đầu hành trình cải cách ma pháp học viện. Dự kiến phát hành: 10-2026.', 'https://cdn.myanimelist.net/images/anime/1222/145668.jpg', 'Sắp phát hành', 20),
  (54, 'Black Clover: Đại Chiến Ma Pháp', 'Yūki Tabata', 'Manga & Shounen', 0, 0, 'Cuộc đại chiến ma pháp tối hậu của vương quốc Tam Diệp chống lại các thế lực cổ xưa. Asta tiếp tục bước đi trên con đường trở thành Ma Pháp Vương. Dự kiến phát hành: 10-2026.', 'https://cdn.myanimelist.net/images/anime/2/88336.jpg', 'Sắp phát hành', 20),
  (55, 'Thám Tử Lừng Danh Conan - Tuyển Tập 2026', 'Gosho Aoyama', 'Trinh thám & Bí ẩn', 0, 0, 'Tuyển tập những vụ án hóc búa nhất của thám tử Edogawa Conan và đối đầu kịch tính cùng Tổ chức Áo đen trong năm 2026. Dự kiến phát hành: 11-2026.', 'https://cdn.myanimelist.net/images/anime/7/75199.jpg', 'Sắp phát hành', 20),
  (56, 'Thám Tử Đã Chết 2 (Tantei wa Mou, Shindeiru)', 'Nigojū', 'Light Novel & Trinh thám', 0, 0, 'Kimizuka Kimihiko tiếp tục khám phá bí mật đằng sau sự ra đi của nữ thám tử thiên tài Siesta và cuộc chiến với tổ chức SPES. Dự kiến phát hành: 11-2026.', 'https://cdn.myanimelist.net/images/anime/1843/115815.jpg', 'Sắp phát hành', 20),
  (57, 'Chuyển Sinh Thành Kiếm - Đại Lộ Kiếm Vũ', 'Yuu Tanaka', 'Kỳ ảo & Phiêu lưu', 0, 0, 'Hành trình vượt qua các đại lục mới của thanh ma kiếm thông minh và cô bé người mèo Fran. Dự kiến phát hành: 11-2026.', 'https://cdn.myanimelist.net/images/anime/1191/127909.jpg', 'Sắp phát hành', 20),
  (58, 'Dragon Ball Super: Bí Ẩn Đa Vũ Trụ Mới', 'Akira Toriyama & Toyotarou', 'Hành động & Siêu nhiên', 0, 0, 'Goku và Vegeta tiếp cận cảnh giới sức mạnh mới trước sự xuất hiện của những thực thể quyền năng bí ẩn từ vũ trụ xa xôi. Dự kiến phát hành: 12-2026.', 'https://cdn.myanimelist.net/images/anime/7/74606.jpg', 'Sắp phát hành', 20),
  (59, 'Majo no Tabitabi: Hành Trình Elaina 2026', 'Jougi Shiraishi', 'Light Novel & Du ký', 0, 0, 'Những mẩu chuyện phiêu lưu lắng đọng và kỳ thú của Phù thủy Tro Tàn Elaina qua các vùng đất huyền bí. Dự kiến phát hành: 12-2026.', 'https://cdn.myanimelist.net/images/anime/1802/108501.jpg', 'Sắp phát hành', 20),
  (60, 'Jujutsu Kaisen: Kỷ Nguyên Hậu Phong Ấn', 'Gege Akutami', 'Shounen & Siêu nhiên', 0, 0, 'Kỷ nguyên đỉnh cao của chú thuật sư và nguyền hồn sau khi phong ấn ngục môn cương được giải trừ. Dự kiến phát hành: 12-2026.', 'https://cdn.myanimelist.net/images/anime/1171/109222.jpg', 'Sắp phát hành', 20);

